def lint():
    """No line may claim a past that is not bound to a stored memory."""
    bad = []
    past = re.compile(r"\b(remember|last time|you told|you said|you gave|you showed|you brought|you caught|you cut|you came|you advised)\b", re.I)
    for c in C.values():
        for cat in ('greet', 'chat'):
            for l in c[cat]:
                if past.search(l['text']) and not l.get('mem'): bad.append((c['id'], l['id']))
        for l in c['recall']:
            if not l.get('mem'): bad.append((c['id'], l['id'], 'recall without memory'))
    assert not bad, bad
def build():
    lint()
    out = dict(version=1, dims=DIMS, anchors=ANCHORS, water=WATER, memory_kinds={k: dict(sig=v[0], sign=v[1]) for k, v in MEMORY.items()}, moods=MOODS,
               tiers=[[0, 'stranger'], [12, 'acquainted'], [30, 'friendly'], [55, 'close'], [80, 'kindred']], characters=C)
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); json.dump(out, open(os.path.join(root, 'assets/social/cast.json'), 'w'), indent=0)
    n = sum(len(c['greet']) + len(c['chat']) + len(c['recall']) + len(c['asleep']) for c in C.values()); print(len(C), 'characters,', n, 'authored lines')
if __name__ == '__main__': build()
